    books_data = json.load(f)

# Get all titles from books.json
titles_books = set(b['title'] for b in books_data['books'])
print("Sample titles from books.json:")
for t in list(titles_books)[:10]:
    print(" ", t)

# Now check book_prices.json manually
with open('/workdir/data/book_prices.json', 'r') as f:
    raw_content = f.read()

# Find all titles from book_prices.json
import re
titles_prices = set()
lines = raw_content.splitlines()
current_obj = {}
in_obj = False
for line in lines:
    line_stripped = line.rstrip()
    if line_stripped.startswith('{'):
        if in_obj and current_obj.get('title') is not None:
            titles_prices.add(current_obj['title'])
            current_obj = {}
        in_obj = True
    if in_obj:
        if '"title":' in line_stripped:
            match = re.search(r'"title":\s*"([^"]+)"', line_stripped)
            if match:
                current_obj['title'] = match.group(1)
            else:
                match = re.search(r'"title":\s*\'([^\']+)\'', line_stripped)
                if match:
                    current_obj['title'] = match.group(1)
        if line_stripped == '}':
            if 'title' in current_obj:
                titles_prices.add(current_obj['title'])
                current_obj = {}
                in_obj = False

